#include "objective_evidence.hpp"
#include "resident/storage/common_store.hpp"
namespace hanmo::resident {
bool same_objective_base_source(const ObjectiveBaseEvidenceSource&a,const ObjectiveBaseEvidenceSource&b){if(a.index()!=b.index())return false;return std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;const auto&y=std::get<T>(b);if constexpr(std::is_same_v<T,LegacyTaskEvidenceRef>)return x.kind==y.kind&&x.id==y.id;else if constexpr(std::is_same_v<T,ObjectiveReceiptRef>)return x.source_domain==y.source_domain&&x.receipt_kind==y.receipt_kind&&x.fact_id==y.fact_id&&x.activity_id==y.activity_id&&x.contribution_use_id==y.contribution_use_id&&x.rule_version==y.rule_version;else if constexpr(std::is_same_v<T,ProfessionalOutcomeSource>)return same_outcome_fact_ref(x.ref,y.ref);else return same_work_result_source(x.source,y.source);},a);}
bool same_objective_base_criterion(const ObjectiveBaseCriterion&a,const ObjectiveBaseCriterion&b){if(a.index()!=b.index())return false;return std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;const auto&y=std::get<T>(b);if constexpr(std::is_same_v<T,LegacyGoalCriterion>)return x.goal_kind==y.goal_kind&&x.rule_version==y.rule_version;else if constexpr(std::is_same_v<T,CraftCriterion>)return x.acceptance_kind==y.acceptance_kind&&x.acceptance_version==y.acceptance_version;else if constexpr(std::is_same_v<T,ProfessionalCriterion>)return x.criterion_kind==y.criterion_kind&&x.criterion_version==y.criterion_version;else return x.criterion_version==y.criterion_version&&x.work_kind==y.work_kind&&x.authorization.program_ref.domain==y.authorization.program_ref.domain&&x.authorization.program_ref.kind==y.authorization.program_ref.kind&&x.authorization.program_ref.id==y.authorization.program_ref.id&&x.authorization.target_line_id==y.authorization.target_line_id&&x.authorization.accepted_task_id==y.authorization.accepted_task_id&&same_terms_revision(x.authorization.terms_revision,y.authorization.terms_revision);},a);}
Status validate_objective_base_source(const ObjectiveBaseEvidenceSource&s,bool used){return std::visit([&](const auto&r)->Status{using T=std::decay_t<decltype(r)>;if constexpr(std::is_same_v<T,LegacyTaskEvidenceRef>){auto k=static_cast<Integer>(r.kind);return k>=0&&k<=4&&!r.id.empty()?common_success():common_failure("InvalidLegacyTaskEvidenceRef");}else if constexpr(std::is_same_v<T,ObjectiveReceiptRef>){if(r.source_domain.empty()||r.receipt_kind.empty()||r.fact_id.empty()||r.rule_version.empty()||(r.activity_id&&r.activity_id->empty())||(r.contribution_use_id&&(!used||r.contribution_use_id->empty())))return common_failure("InvalidObjectiveReceiptRef");return common_success();}else if constexpr(std::is_same_v<T,ProfessionalOutcomeSource>)return validate_outcome_fact_ref(r.ref);else return std::visit([](const auto&v)->Status{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,LegacyAppeaseWork>)return v.work_completion_fact_id.empty()?common_failure("InvalidWorkEvidenceSource"):common_success();else return v.fact_id.empty()?common_failure("InvalidWorkEvidenceSource"):common_success();},r.source);},s);}
}
